import XCTest
import SwiftData
@testable import DueDay
final class PeriodCalculatorTests:XCTestCase{
 let c=PeriodCalculator()
 func testMonthEnd(){let d=CalendarDates.date(2024,1,31);XCTAssertEqual(CalendarDates.calendar.component(.day,from:c.dueDate(first:d,cycle:.monthly,sequence:2)),29);XCTAssertEqual(CalendarDates.calendar.component(.day,from:c.dueDate(first:d,cycle:.monthly,sequence:3)),31);XCTAssertEqual(CalendarDates.calendar.component(.day,from:c.dueDate(first:d,cycle:.monthly,sequence:4)),30)}
 func testQuarterAndYear(){let d=CalendarDates.date(2024,1,31);XCTAssertEqual(CalendarDates.calendar.component(.month,from:c.dueDate(first:d,cycle:.quarterly,sequence:2)),4);XCTAssertEqual(CalendarDates.calendar.component(.year,from:c.dueDate(first:d,cycle:.yearly,sequence:2)),2025)}
 func testLeapYear(){let d=CalendarDates.date(2024,2,29);XCTAssertEqual(CalendarDates.calendar.component(.day,from:c.dueDate(first:d,cycle:.yearly,sequence:2)),28);XCTAssertEqual(CalendarDates.calendar.component(.day,from:c.dueDate(first:d,cycle:.yearly,sequence:5)),29)}
 func testOnce(){let d=CalendarDates.date(2026,8,14);XCTAssertEqual(c.dueDate(first:d,cycle:.once,sequence:7),d);XCTAssertNil(c.next(first:d,cycle:.once,after:d.addingTimeInterval(86400)))}
 func testKeysAndBoundary(){XCTAssertEqual(c.key(1),"period-000001");let d=CalendarDates.date(2026,8,14);XCTAssertEqual(c.next(first:d,cycle:.monthly,after:d),d);XCTAssertEqual(CalendarDates.calendar.component(.month,from:c.next(first:d,cycle:.monthly,after:d.addingTimeInterval(86400))!),9)}
 func testStatusAndUnknown(){XCTAssertEqual(BillFormatters.amount(nil),"金额待确认");XCTAssertEqual(BillFormatters.amount(12345),"¥123.45");XCTAssertEqual(PeriodStatus.paid.label,"已完成");XCTAssertEqual(PlanStatus.archived.label,"已归档")}
 func testMoneyParserExactBoundaries(){XCTAssertEqual(try! MoneyParser.parseCents("128.88"),12888);XCTAssertEqual(try! MoneyParser.parseCents("0.1"),10);XCTAssertThrowsError(try MoneyParser.parseCents("1.005"));XCTAssertThrowsError(try MoneyParser.parseCents("-1.00"));XCTAssertThrowsError(try MoneyParser.parseCents(""))}
 func testInstallmentMaterializerStopsAtPositiveTotal(){let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true));let context=ModelContext(container);let plan=BillingPlan(id:"plan-installments",title:"分期账单",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20),totalInstallments:2);context.insert(plan);try! context.save();try! BillingMaterializer.run(context,[plan]);let periods=(try! context.fetch(FetchDescriptor<BillPeriod>())).sorted{$0.sequence<$1.sequence};XCTAssertEqual(periods.count,2);XCTAssertEqual(periods.map(\.sequence),[1,2])}
 func testReminderRuleSynchronizerCanonicalIDsAndRemoval(){let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true));let context=ModelContext(container);let plan=BillingPlan(id:"plan-rules",title:"提醒账单",firstDueDate:CalendarDates.date(2026,8,20),reminderDays:[3,1],reminderHour:8);context.insert(plan);try! context.save();try! ReminderRuleSynchronizer.sync(context:context,plan:plan);var rules=try! context.fetch(FetchDescriptor<ReminderRule>());XCTAssertEqual(Set(rules.map(\.id)),["reminder-plan-rules-1","reminder-plan-rules-3"]);plan.reminderDays=[0];plan.reminderHour=10;try! ReminderRuleSynchronizer.sync(context:context,plan:plan);try! context.save();rules=try! context.fetch(FetchDescriptor<ReminderRule>());XCTAssertEqual(rules.count,1);XCTAssertEqual(rules[0].id,"reminder-plan-rules-0");XCTAssertEqual(rules[0].localHour,10);XCTAssertEqual(rules[0].sortOrder,0)}
 func testRelative(){let d=CalendarDates.date(2026,8,14);XCTAssertEqual(BillFormatters.relative(d,today:d),"今天");XCTAssertEqual(BillFormatters.relative(CalendarDates.date(2026,8,13),today:d),"逾期 1 天")}
 func testCalendarSummaryGroupsStatusesAndCounts(){let plan=BillingPlan(id:"calendar-summary",title:"日历测试",firstDueDate:CalendarDates.date(2026,8,20));let overdue=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,20));let paid=BillPeriod(plan:plan,sequence:2,dueDate:CalendarDates.date(2026,8,20));paid.statusRaw=PeriodStatus.paid.rawValue;let skipped=BillPeriod(plan:plan,sequence:3,dueDate:CalendarDates.date(2026,8,20));skipped.statusRaw=PeriodStatus.skipped.rawValue;let pending=BillPeriod(plan:plan,sequence:4,dueDate:CalendarDates.date(2026,8,22));let summary=CalendarPresentation.summary(for:CalendarDates.date(2026,8,20),periods:[overdue,paid,skipped,pending],today:CalendarDates.date(2026,8,21));XCTAssertEqual(summary.totalCount,3);XCTAssertEqual(summary.overdueCount,1);XCTAssertEqual(summary.pendingCount,1);XCTAssertEqual(summary.paidCount,1);XCTAssertEqual(summary.skippedCount,1);XCTAssertEqual(summary.statuses,[.overdue,.paid,.skipped]);let future=CalendarPresentation.summary(for:CalendarDates.date(2026,8,22),periods:[overdue,paid,skipped,pending],today:CalendarDates.date(2026,8,21));XCTAssertEqual(future.statuses,[.pending])}
 func testCalendarInitialPositionChoosesNextPendingDate(){let plan=BillingPlan(id:"calendar-position",title:"日历定位",firstDueDate:CalendarDates.date(2026,8,21));let period=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,21));let position=CalendarPresentation.initialPosition(periods:[period],today:CalendarDates.date(2026,8,18));XCTAssertEqual(position.month,CalendarDates.date(2026,8,1));XCTAssertEqual(position.date,CalendarDates.date(2026,8,21));let next=BillPeriod(plan:plan,sequence:2,dueDate:CalendarDates.date(2026,9,21));let nextPosition=CalendarPresentation.initialPosition(periods:[next],today:CalendarDates.date(2026,8,18));XCTAssertEqual(nextPosition.month,CalendarDates.date(2026,9,1));XCTAssertEqual(nextPosition.date,CalendarDates.date(2026,9,21))}
 func testCalendarFirstDateUsesPendingBeforeHistory(){let plan=BillingPlan(id:"calendar-first",title:"切月定位",firstDueDate:CalendarDates.date(2026,8,1));let paid=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,1));paid.statusRaw=PeriodStatus.paid.rawValue;let pending=BillPeriod(plan:plan,sequence:2,dueDate:CalendarDates.date(2026,8,20));XCTAssertEqual(CalendarPresentation.firstDate(in:CalendarDates.date(2026,8,1),periods:[paid,pending],today:CalendarDates.date(2026,8,18)),CalendarDates.date(2026,8,20))}
 func testNotificationDaysAndSameDay(){let plan=BillingPlan(id:"plan-days",title:"房贷",amountInCents:12345,cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20),reminderDays:[3,0],reminderHour:9);let period=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,20));let built=NotificationScheduleBuilder(calendar:CalendarDates.calendar).build(plans:[plan],periods:[period],now:CalendarDates.date(2026,8,14));XCTAssertEqual(built.count,2);XCTAssertEqual(CalendarDates.calendar.component(.day,from:built[0].fireAt),17);XCTAssertEqual(CalendarDates.calendar.component(.hour,from:built[0].fireAt),9);XCTAssertEqual(CalendarDates.calendar.component(.day,from:built[1].fireAt),20)}
 func testNotificationExcludesPastAndInactive(){let due=CalendarDates.date(2026,8,14);let plan=BillingPlan(id:"plan-exclude",title:"订阅",cycle:.monthly,firstDueDate:due,reminderDays:[0],reminderHour:9);let past=BillPeriod(plan:plan,sequence:1,dueDate:due);let future=BillPeriod(plan:plan,sequence:2,dueDate:CalendarDates.date(2026,8,20));future.statusRaw=PeriodStatus.paid.rawValue;let paused=BillingPlan(id:"plan-paused",title:"暂停",cycle:.monthly,firstDueDate:due,reminderDays:[0],reminderHour:9,status:.paused);let pausedPeriod=BillPeriod(plan:paused,sequence:1,dueDate:CalendarDates.date(2026,8,20));let built=NotificationScheduleBuilder().build(plans:[plan,paused],periods:[past,future,pausedPeriod],now:due.addingTimeInterval(36000));XCTAssertTrue(built.isEmpty)}
 func testNotificationUsesPeriodSnapshotAndEditingPlanDoesNotChangeIt(){let due=CalendarDates.date(2026,8,20);let plan=BillingPlan(id:"plan-snapshot",title:"快照账单",cycle:.monthly,firstDueDate:due,reminderDays:[7],reminderHour:2);let period=BillPeriod(plan:plan,sequence:1,dueDate:due);period.reminderDays=[0,0,367,-1];period.reminderHour=10;plan.reminderDays=[30];plan.reminderHour=1;let built=NotificationScheduleBuilder().build(plans:[plan],periods:[period],now:CalendarDates.date(2026,8,14));XCTAssertEqual(built.count,1);XCTAssertEqual(CalendarDates.calendar.component(.day,from:built[0].fireAt),20);XCTAssertEqual(CalendarDates.calendar.component(.hour,from:built[0].fireAt),10);XCTAssertEqual(built[0].id,NotificationScheduleBuilder().notificationID(planID:plan.id,periodKey:period.periodKey,daysBefore:0))}
 func testNotificationRejectsInvalidValuesAndIncludesDayZeroAndDay366(){let now=CalendarDates.date(2026,8,14);let day366=CalendarDates.calendar.date(byAdding:.day,value:366,to:now)!;let p1=BillingPlan(id:"plan-boundary-0",title:"当天",firstDueDate:now,reminderDays:[0],reminderHour:9);let p2=BillingPlan(id:"plan-boundary-366",title:"第366天",firstDueDate:day366,reminderDays:[0],reminderHour:9);let p3=BillingPlan(id:"plan-boundary-367",title:"第367天",firstDueDate:CalendarDates.calendar.date(byAdding:.day,value:367,to:now)!,reminderDays:[0],reminderHour:9);let invalidDays=BillingPlan(id:"plan-invalid-days",title:"非法天数",firstDueDate:CalendarDates.date(2026,8,20),reminderDays:[-1,367],reminderHour:9);let invalidHour=BillingPlan(id:"plan-invalid-hour",title:"非法时间",firstDueDate:CalendarDates.date(2026,8,20),reminderDays:[0],reminderHour:24);let plans=[p1,p2,p3,invalidDays,invalidHour];let periods=plans.map{BillPeriod(plan:$0,sequence:1,dueDate:$0.firstDueDate)};let built=NotificationScheduleBuilder().build(plans:plans,periods:periods,now:now);XCTAssertEqual(Set(built.map(\.id)),Set([NotificationScheduleBuilder().notificationID(planID:p1.id,periodKey:periods[0].periodKey,daysBefore:0),NotificationScheduleBuilder().notificationID(planID:p2.id,periodKey:periods[1].periodKey,daysBefore:0)]))}
 func testNotificationStableIDLimitAndSorting(){let builder=NotificationScheduleBuilder();var plans:[BillingPlan]=[];var periods:[BillPeriod]=[];for i in 0..<70{let p=BillingPlan(id:"plan-\(i)",title:"账单 \(i)",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20+i),reminderDays:[0],reminderHour:9);plans.append(p);periods.append(BillPeriod(plan:p,sequence:1,dueDate:CalendarDates.date(2026,8,20+i)))};let built=builder.build(plans:plans,periods:periods,now:CalendarDates.date(2026,8,14));XCTAssertEqual(built.count,64);XCTAssertEqual(built.first?.id,builder.notificationID(planID:"plan-0",periodKey:"period-000001",daysBefore:0));XCTAssertEqual(built.first?.id,builder.notificationID(planID:"plan-0",periodKey:"period-000001",daysBefore:0));XCTAssertLessThanOrEqual(built[0].fireAt,built[63].fireAt)}
 func testNotificationUnknownAmountDoesNotInventValue(){let due=CalendarDates.date(2026,8,20);let plan=BillingPlan(id:"plan-unknown",title:"水电费",cycle:.monthly,firstDueDate:due,reminderDays:[3],reminderHour:9);let period=BillPeriod(plan:plan,sequence:1,dueDate:due);let notification=try! XCTUnwrap(NotificationScheduleBuilder().build(plans:[plan],periods:[period],now:CalendarDates.date(2026,8,14)).first);XCTAssertTrue(notification.title.contains("水电费"));XCTAssertFalse(notification.body.contains("¥"));XCTAssertTrue(notification.body.contains("还有 6 天到期"))}
 func testCoordinatorReconcileWithFakeGateway() async {let suite="DueDay.NotificationTests.\(UUID().uuidString)";let fake=FakeNotificationGateway();let defaults=UserDefaults(suiteName:suite)!;let coordinator=await NotificationCoordinator(gateway:fake,defaults:defaults);await coordinator.refreshPermission();let due=CalendarDates.date(2026,8,20);let plan=BillingPlan(id:"plan-fake",title:"测试账单",cycle:.monthly,firstDueDate:due,reminderDays:[3],reminderHour:9);let period=BillPeriod(plan:plan,sequence:1,dueDate:due);await coordinator.reconcile(plans:[plan],periods:[period],now:CalendarDates.date(2026,8,14));XCTAssertEqual(fake.added.count,1);let firstID=fake.added[0].id;await coordinator.reconcile(plans:[plan],periods:[period],now:CalendarDates.date(2026,8,14));XCTAssertEqual(fake.removed,[firstID]);XCTAssertEqual(fake.added.count,2);defaults.removePersistentDomain(forName:suite)}
 func testFlutterV1FixtureImport(){let document=try! BackupCodec().decode(flutterFixture());XCTAssertEqual(document.format,BackupCodec.format);XCTAssertEqual(document.version,1);XCTAssertEqual(document.plans.count,1);XCTAssertNil(document.plans[0].amountInCents);XCTAssertEqual(document.periods[0].id,"plan-flutter-1::period-000001")}
 func testBackupUnknownAmountAndRoundTrip(){let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true));let context=ModelContext(container);let plan=BillingPlan(id:"plan-roundtrip",title:"水电费",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20),reminderDays:[3],reminderHour:9);context.insert(plan);context.insert(ReminderRule(id:"reminder-plan-roundtrip-3",planId:plan.id,daysBeforeDue:3,localHour:9));context.insert(BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,20)));try! context.save();let data=try! BackupService().export(context:context,notificationsEnabled:true,now:CalendarDates.date(2026,8,14));let decoded=try! BackupCodec().decode(data);XCTAssertEqual(decoded.plans.count,1);XCTAssertNil(decoded.plans[0].amountInCents);XCTAssertNil(decoded.periods[0].amountInCents);let other=ModelContext(try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true)));try! BackupService().replace(with:data,context:other);let restored=try! other.fetch(FetchDescriptor<BillPeriod>());XCTAssertEqual(restored.count,1);XCTAssertNil(restored[0].amountInCents)}
 func testBackupRejectsVersionStatusAndForeignKey(){let codec=BackupCodec();var root=try! JSONSerialization.jsonObject(with:fixtureData()) as! [String:Any];root["version"]=2;XCTAssertThrowsError(try codec.decode(try! JSONSerialization.data(withJSONObject:root)));root=try! JSONSerialization.jsonObject(with:fixtureData()) as! [String:Any];var periods=root["periods"] as! [[String:Any]];periods[0]["planId"]="missing";root["periods"]=periods;XCTAssertThrowsError(try codec.decode(try! JSONSerialization.data(withJSONObject:root)));root=try! JSONSerialization.jsonObject(with:fixtureData()) as! [String:Any];var plans=root["plans"] as! [[String:Any]];plans[0]["status"]="unknown";root["plans"]=plans;XCTAssertThrowsError(try codec.decode(try! JSONSerialization.data(withJSONObject:root)))}
 func testBackupRejectsOversizedAndPreservesExistingOnFailure(){let codec=BackupCodec();XCTAssertThrowsError(try codec.decode(Data(repeating:0,count:BackupCodec.maxBytes+1)));let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true));let context=ModelContext(container);context.insert(BillingPlan(id:"old-plan",title:"旧数据",firstDueDate:CalendarDates.date(2026,8,20)));try! context.save();XCTAssertThrowsError(try BackupService().replace(with:Data("{}".utf8),context:context));XCTAssertEqual(try! context.fetch(FetchDescriptor<BillingPlan>()).first?.title,"旧数据")}
 func testSuccessfulRestoreThenNotificationReconcile() async {let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true));let context=ModelContext(container);let summary=try! BackupService().replace(with:fixtureData(),context:context);XCTAssertEqual(summary.planCount,1);let fake=FakeNotificationGateway();let suite="DueDay.BackupTests.\(UUID().uuidString)";let defaults=UserDefaults(suiteName:suite)!;let coordinator=await NotificationCoordinator(gateway:fake,defaults:defaults);await coordinator.refreshPermission();let plans=try! context.fetch(FetchDescriptor<BillingPlan>());let periods=try! context.fetch(FetchDescriptor<BillPeriod>());await coordinator.reconcile(plans:plans,periods:periods,now:CalendarDates.date(2026,8,1));XCTAssertEqual(fake.added.count,1);defaults.removePersistentDomain(forName:suite)}
 func testBillSearchMatcherSupportsMultipleBusinessFields(){let plan=BillingPlan(id:"search",title:"招商银行信用卡",category:.creditCard,institution:"招商银行",accountSuffix:"9407",amountInCents:12888,firstDueDate:CalendarDates.date(2026,8,21),note:"日常主卡");let period=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,21));XCTAssertTrue(BillSearchMatcher.matches(period,query:"招商 9407"));XCTAssertTrue(BillSearchMatcher.matches(period,query:"信用卡 待支付"));XCTAssertTrue(BillSearchMatcher.matches(period,query:"日常主卡"));XCTAssertFalse(BillSearchMatcher.matches(period,query:"房贷"))}
 func testBillListSelectionUsesRepresentativeHistory() { let active=BillingPlan(id:"active",title:"进行中",firstDueDate:CalendarDates.date(2026,8,1)); let paidOnly=BillingPlan(id:"paid-only",title:"已完成历史",firstDueDate:CalendarDates.date(2026,8,2)); let paused=BillingPlan(id:"paused",title:"暂停",firstDueDate:CalendarDates.date(2026,8,3),status:.paused); let archived=BillingPlan(id:"archived",title:"归档",firstDueDate:CalendarDates.date(2026,8,4),status:.archived); let activePaid=BillPeriod(plan:active,sequence:1,dueDate:CalendarDates.date(2026,8,1)); activePaid.statusRaw=PeriodStatus.paid.rawValue; let activePending=BillPeriod(plan:active,sequence:2,dueDate:CalendarDates.date(2026,8,10)); let paidHistory=BillPeriod(plan:paidOnly,sequence:1,dueDate:CalendarDates.date(2026,8,2)); paidHistory.statusRaw=PeriodStatus.paid.rawValue; let pausedPaid=BillPeriod(plan:paused,sequence:1,dueDate:CalendarDates.date(2026,8,3)); pausedPaid.statusRaw=PeriodStatus.paid.rawValue; let pausedPending=BillPeriod(plan:paused,sequence:2,dueDate:CalendarDates.date(2026,8,8)); let archivedPaid=BillPeriod(plan:archived,sequence:1,dueDate:CalendarDates.date(2026,8,4)); archivedPaid.statusRaw=PeriodStatus.paid.rawValue; let archivedPending=BillPeriod(plan:archived,sequence:2,dueDate:CalendarDates.date(2026,8,9)); let plans=[active,paidOnly,paused,archived]; let periods=[activePaid,activePending,paidHistory,pausedPaid,pausedPending,archivedPaid,archivedPending]; XCTAssertEqual(BillListSelection.representatives(plans:plans,periods:periods,filter:.all).map(\.id),[paidHistory.id,pausedPending.id,activePending.id]); XCTAssertEqual(BillListSelection.representatives(plans:plans,periods:periods,filter:.pending).map(\.id),[activePending.id]); XCTAssertEqual(BillListSelection.representatives(plans:plans,periods:periods,filter:.paid).map(\.id),[activePaid.id,paidHistory.id,pausedPaid.id,archivedPaid.id]); XCTAssertEqual(BillListSelection.representatives(plans:plans,periods:periods,filter:.paused).map(\.id),[pausedPending.id]); XCTAssertEqual(BillListSelection.representatives(plans:plans,periods:periods,filter:.archived).map(\.id),[archivedPending.id]) }
 func testDashboardSummaryExcludesSkippedAndSeparatesUnknown() { let plan=BillingPlan(id:"summary",title:"统计",firstDueDate:CalendarDates.date(2026,8,1)); let pending=BillPeriod(plan:plan,sequence:1,dueDate:CalendarDates.date(2026,8,5)); pending.amountInCents=10000; let pendingUnknown=BillPeriod(plan:plan,sequence:2,dueDate:CalendarDates.date(2026,8,6)); let paid=BillPeriod(plan:plan,sequence:3,dueDate:CalendarDates.date(2026,8,7)); paid.amountInCents=20000; paid.statusRaw=PeriodStatus.paid.rawValue; let paidUnknown=BillPeriod(plan:plan,sequence:4,dueDate:CalendarDates.date(2026,8,8)); paidUnknown.statusRaw=PeriodStatus.paid.rawValue; let skipped=BillPeriod(plan:plan,sequence:5,dueDate:CalendarDates.date(2026,8,9)); skipped.amountInCents=99900; skipped.statusRaw=PeriodStatus.skipped.rawValue; let summary=DashboardSummary.summary(periods:[pending,pendingUnknown,paid,paidUnknown,skipped],month:CalendarDates.date(2026,8,14)); XCTAssertEqual(summary.pendingKnownCents,10000); XCTAssertEqual(summary.paidKnownCents,20000); XCTAssertEqual(summary.unknownCount,2); XCTAssertEqual(summary.pendingCount,2); XCTAssertEqual(summary.paidCount,2); XCTAssertEqual(summary.progressDenominator,4); XCTAssertEqual(summary.completion,0.5); XCTAssertEqual(DashboardSummary.futureMonths(periods:[pending],from:CalendarDates.date(2026,8,14),count:6).count,6) }
 func testMaterializerWindowAndOldPlanDoesNotCreateHistory() { let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true)); let context=ModelContext(container); let plan=BillingPlan(id:"old-plan",title:"老计划",cycle:.monthly,firstDueDate:CalendarDates.date(2010,1,31)); context.insert(plan); try! context.save(); let reference=CalendarDates.date(2026,8,14); try! BillingMaterializer.run(context,[plan],referenceDate:reference); let periods=try! context.fetch(FetchDescriptor<BillPeriod>()); XCTAssertEqual(periods.count,8); XCTAssertTrue(periods.allSatisfy { $0.dueDate >= CalendarDates.date(2026,7,1) && $0.dueDate <= CalendarDates.date(2027,2,28) }); XCTAssertGreaterThan(periods.map(\.sequence).min() ?? 0, 1); try! BillingMaterializer.run(context,[plan],referenceDate:reference); XCTAssertEqual(try! context.fetch(FetchDescriptor<BillPeriod>()).count,8) }
 func testMaterializerIncludesWindowEdgesAndOnceRules() { let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true)); let context=ModelContext(container); let edgeStart=BillingPlan(id:"edge-start",title:"窗口开始",cycle:.monthly,firstDueDate:CalendarDates.date(2026,7,1)); let edgeEnd=BillingPlan(id:"edge-end",title:"窗口结束",cycle:.monthly,firstDueDate:CalendarDates.date(2027,2,28)); let onceBefore=BillingPlan(id:"once-before",title:"窗口前一次",cycle:.once,firstDueDate:CalendarDates.date(2026,6,30)); let onceInside=BillingPlan(id:"once-inside",title:"窗口内一次",cycle:.once,firstDueDate:CalendarDates.date(2026,7,1)); let onceAfter=BillingPlan(id:"once-after",title:"窗口后一次",cycle:.once,firstDueDate:CalendarDates.date(2027,3,1)); [edgeStart,edgeEnd,onceBefore,onceInside,onceAfter].forEach(context.insert); try! context.save(); try! BillingMaterializer.run(context,[edgeStart,edgeEnd,onceBefore,onceInside,onceAfter],referenceDate:CalendarDates.date(2026,8,14)); let ids=Set((try! context.fetch(FetchDescriptor<BillPeriod>())).map(\.planId)); XCTAssertEqual(ids,Set(["edge-start","edge-end","once-inside"])) }
 func testMaterializerSkipsPausedArchivedAndPreservesOutsideHistory() { let container=try! ModelContainer(for:BillingPlan.self,BillPeriod.self,ReminderRule.self,configurations:ModelConfiguration(isStoredInMemoryOnly:true)); let context=ModelContext(container); let active=BillingPlan(id:"active-preserve",title:"保留历史",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20)); let paused=BillingPlan(id:"paused-nope",title:"暂停",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20),status:.paused); let archived=BillingPlan(id:"archived-nope",title:"归档",cycle:.monthly,firstDueDate:CalendarDates.date(2026,8,20),status:.archived); let historical=BillPeriod(plan:active,sequence:1,dueDate:CalendarDates.date(2026,6,20)); [active,paused,archived].forEach(context.insert); context.insert(historical); try! context.save(); try! BillingMaterializer.run(context,[active,paused,archived],referenceDate:CalendarDates.date(2026,8,14)); let periods=try! context.fetch(FetchDescriptor<BillPeriod>()); XCTAssertTrue(periods.contains(where: { $0.id == historical.id && $0.dueDate == CalendarDates.date(2026,6,20) })); XCTAssertFalse(periods.contains(where: { $0.planId == paused.id || $0.planId == archived.id })) }
