final class FakeNotificationGateway: NotificationGateway {
 var status:NotificationAuthorizationStatus = .authorized; var added:[ScheduledNotification]=[]; var removed:[String]=[]; var openSettingsCount=0
 func authorizationStatus() async -> NotificationAuthorizationStatus { status }
 func requestAuthorization() async throws -> Bool { status = .authorized; return true }
 func openSettings(){openSettingsCount += 1}
 func pendingIdentifiers() async -> [String] { added.map(\.id).filter{!removed.contains($0)} }
 func add(_ notification:ScheduledNotification) async throws {added.append(notification)}
 func remove(ids:[String]) async throws {removed.append(contentsOf:ids)}
}
